-- Conteudo didatico completo (Etapas + quiz) das 9 aulas do Curso Basico,
-- extraido diretamente dos arquivos da vault "Hub do Treinador" por script.
-- Complementa a migration 009 (que so tinha nome + carga horaria).

alter table public.subthemes add column if not exists conteudo jsonb;

update public.subthemes set conteudo = $json0${"duracao":"1h","norma":"IN 28/2024 CBMSC | NBR 14276 Anexo B","modulo":"Noções de Extinção","contexto":{"titulo":"Etapa 1 — Contexto (5 min)","corpo_md":"**Dado de abertura:** Em 2023, o CBMSC atendeu mais de 9.000 ocorrências de incêndio em Santa Catarina. Estudos internacionais indicam que nos primeiros 3 minutos de um incêndio, um brigadista orgânico corretamente treinado pode extinguir 80% dos princípios de incêndio sem a chegada do Corpo de Bombeiros.\n\n**Pergunta disparadora para a turma:**\n> \"O que vocês acham que alimenta um incêndio? O que faria ele parar?\"\n\nRegistre as respostas no quadro — elas serão revisitadas ao final da etapa 2."},"explicacao":{"titulo":"Etapa 2 — Explicação (35 min)","corpo_md":"### 2.1 Triângulo do Fogo\nTrês elementos necessários para a combustão:\n- **Combustível** — qualquer material que pode queimar (sólido, líquido ou gasoso)\n- **Comburente** — oxigênio do ar (mínimo ~16% para manter a combustão; ar normal tem ~21%)\n- **Calor** — energia de ativação para iniciar e manter a reação\n\n> Remova qualquer um dos três → o fogo se apaga.\n\n### 2.2 Tetraedro do Fogo (modelo atual)\nA ciência moderna acrescenta uma quarta face:\n- **Reação em cadeia** — processo autossustentado de radicais livres que mantém a combustão mesmo após remoção parcial dos outros elementos\n\n> Agentes halogenados (ex: FM-200) atuam quebrando a reação em cadeia.\n\n### 2.3 Tipos de Combustão\n\n| Tipo | Características | Produtos |\n|------|----------------|----------|\n| Completa | Oxigênio suficiente, chama azulada | CO₂ + H₂O |\n| Incompleta | Falta de O₂, fumaça escura | CO (monóxido) + fuligem + partículas |\n\n> ⚠️ O **monóxido de carbono (CO)** é inodoro, incolor e responsável por 50–80% das mortes em incêndios. A fumaça mata antes das chamas.\n\n### 2.4 Propagação do Calor\n\n| Modo | Como age | Exemplo |\n|------|----------|---------|\n| **Condução** | Transferência entre sólidos em contato | Barra metálica aquecida na extremidade |\n| **Convecção** | Movimento de gases/fluidos aquecidos | Fumaça que sobe pelo corredor |\n| **Irradiação** | Ondas eletromagnéticas no espaço | Calor sentido a distância de um incêndio |\n\n### 2.5 Fases do Incêndio\n\n1. **Ignição** — início da combustão, fogo pequeno e controlável\n2. **Crescimento** — propagação pelo combustível disponível\n3. **Flashover** — ignição simultânea de todos os materiais combustíveis do ambiente; temperatura chega a 600–900°C; **ponto sem retorno para fuga**\n4. **Pleno desenvolvimento** — temperatura máxima, consumo total do oxigênio disponível\n5. **Decaimento** — combustível ou oxigênio se esgota\n\n> 🔴 O brigadista orgânico deve agir ANTES do flashover. Após o flashover, evacuação imediata.\n\n### 2.6 Pontos Críticos de Temperatura\n\n| Termo | Definição |\n|-------|-----------|\n| Ponto de fulgor | Temperatura mínima para emissão de vapores inflamáveis (sem chama sustentada) |\n| Ponto de ignição | Temperatura onde a combustão se sustenta com fonte de calor |\n| Temperatura de autoignição | Combustão espontânea sem fonte externa |"},"recurso":{"titulo":"Etapa 3 — Vídeo / Recurso Prático (15 min)","corpo_md":"**Opção A — Vídeo:**\nBuscar no YouTube: *\"Teoria do Fogo Corpo de Bombeiros\"* — preferir vídeos dos CBMSC, CBMMG ou CBMERJ com menos de 15 min.\n\n**Opção B — Atividade de fixação (sem vídeo):**\nDistribuir uma folha com o diagrama do tetraedro em branco. Os alunos preenchem as 4 faces e escrevem um exemplo de extinção para cada face removida.\n\n| Face removida | Método de extinção | Exemplo |\n|---------------|-------------------|---------|\n| Combustível | Isolamento | Retirar o botijão de gás da área |\n| Comburente | Abafamento | Tampar panela em chamas |\n| Calor | Resfriamento | Aplicar água no foco |\n| Reação em cadeia | Inibição química | Usar extintor de pó ABC |"},"verificacao":{"titulo":"Etapa 4 — Verificação de Aprendizagem (5 min)","evidencia":"Evidência documental: registrar nome do aluno e respostas para auditoria/vistoria CBMSC.","questoes":[{"pergunta":"Qual elemento foi ACRESCENTADO ao triângulo do fogo para formar o tetraedro?","opcoes":[{"texto":"Pressão","correta":false},{"texto":"Reação em cadeia","correta":true},{"texto":"Fumaça","correta":false},{"texto":"Temperatura ambiente","correta":false}]},{"pergunta":"A fumaça escura e densa indica:","opcoes":[{"texto":"Combustão completa com muito oxigênio","correta":false},{"texto":"Alta temperatura no ambiente","correta":false},{"texto":"Combustão incompleta com falta de oxigênio","correta":true},{"texto":"Presença de metais na combustão","correta":false}]},{"pergunta":"O calor de uma placa metálica quente se propaga para outra peça encostada principalmente por:","opcoes":[{"texto":"Convecção","correta":false},{"texto":"Irradiação","correta":false},{"texto":"Condução","correta":true},{"texto":"Reação em cadeia","correta":false}]},{"pergunta":"O flashover é:","opcoes":[{"texto":"A fase inicial controlável do incêndio","correta":false},{"texto":"A ignição simultânea de todos os materiais combustíveis do ambiente","correta":true},{"texto":"O momento em que o incêndio começa a se apagar","correta":false},{"texto":"Um tipo de extintor de incêndio","correta":false}]},{"pergunta":"Para extinguir um incêndio pelo método de abafamento, qual elemento do tetraedro é removido?","opcoes":[{"texto":"Combustível","correta":false},{"texto":"Reação em cadeia","correta":false},{"texto":"Calor","correta":false},{"texto":"Comburente (oxigênio)","correta":true}]}]},"fechamento":{"titulo":"Etapa 5 — Fechamento (2 min)","pontos_chave":["Fogo = 4 elementos (tetraedro) — remova qualquer um e o fogo se apaga","A fumaça mata antes das chamas — CO inodoro e incolor é o maior inimigo","Flashover é o limite — antes: combata; depois: abandone imediatamente"],"ponte":"Agora que entendemos o que é o fogo e como ele se comporta, precisamos identificar os **tipos** de incêndio que podemos encontrar nesta empresa — porque cada tipo exige um extintor diferente. É isso que veremos em B2: as Classes de Incêndio."}}$json0$::jsonb where name = 'B1 — Teoria do Fogo';
update public.subthemes set conteudo = $json1${"duracao":"1h","norma":"IN 28/2024 CBMSC | NBR 14276 Anexo B","modulo":"Noções de Extinção","contexto":{"titulo":"Etapa 1 — Contexto (5 min)","corpo_md":"**Caso real de abertura:**\nEm 2019, um funcionário de um escritório tentou apagar um princípio de incêndio em uma impressora usando um extintor de água pressurizada. O equipamento explodiu, causando queimaduras graves. O erro: incêndio classe C (elétrico) com extintor de água.\n\n**Ponto central:**\n> Usar o extintor errado pode ser mais perigoso do que não usar nenhum.\n\n**Pergunta para a turma:**\n> \"Se pegar fogo na fritadeira da cozinha aqui, o que vocês fariam?\""},"explicacao":{"titulo":"Etapa 2 — Explicação (35 min)","corpo_md":"> ⚠️ Regra obrigatória (IN 28/2024): sempre listar **todas as 6 classes**: A, B, C, D, K e **L**.\n\n### Classe A — Sólidos Combustíveis\n- **Material:** madeira, papel, tecido, borracha, plástico comum\n- **Característica:** queimam em superfície E em profundidade; deixam resíduo (cinza, brasa)\n- **Extinção:** resfriamento (água) é o mais eficiente — precisa penetrar no material\n- **Extintores:** água pressurizada, espuma, pó ABC\n- **Exemplo na empresa:** arquivo de papel, mobiliário de madeira, embalagens\n\n### Classe B — Líquidos e Gases Inflamáveis\n- **Material:** gasolina, álcool, diesel, tintas, GLP, GN, solventes\n- **Característica:** queimam apenas na superfície; **NUNCA usar água** (espirra e espalha o fogo)\n- **Extinção:** abafamento (isolar da superfície) ou inibição da reação\n- **Extintores:** CO₂, pó BC, pó ABC, espuma mecânica\n- **Exemplo na empresa:** copa com botijão de gás, almoxarifado com solventes\n\n### Classe C — Equipamentos Elétricos Energizados\n- **Material:** painéis elétricos, computadores, fios, motores em operação\n- **Característica:** o risco é o choque elétrico; **NUNCA usar água ou espuma**\n- **Extinção:** agente não condutor elétrico\n- **Extintores:** CO₂, pó BC, pó ABC *(após desligar a energia, pode virar classe A)*\n- **Exemplo na empresa:** sala de servidores, quadros de distribuição, ar-condicionado\n\n### Classe D — Metais Pirofóricos\n- **Material:** magnésio (Mg), titânio (Ti), sódio (Na), potássio (K), alumínio em pó\n- **Característica:** reagem violentamente com água; temperatura de combustão >1.000°C\n- **Extinção:** pó especial para metais (grafite, areia seca, cloreto de sódio seco)\n- **Extintores:** extintor classe D específico — **nunca água, CO₂ ou pó ABC**\n- **Exemplo na empresa:** oficinas de usinagem, laboratórios químicos, indústrias aeronáuticas\n\n### Classe K — Óleos e Gorduras Vegetais e Animais\n- **Material:** óleo de fritura, azeite, manteiga, gordura animal, margarinas\n- **Característica:** temperatura de autoignição baixa; reagem com água causando explosão de vapor\n- **Extinção:** saponificação — agente úmido reage com a gordura formando uma camada sólida\n- **Extintores:** extintor classe K (agente úmido específico); **NUNCA água ou pó**\n- **Exemplo na empresa:** cozinha industrial, refeitório, restaurante\n\n### ⭐ Classe L — Baterias e Células de Lítio\n- **Material:** baterias de lítio-íon, lítio-polímero (celulares, notebooks, ferramentas sem fio, veículos elétricos, nobreaks, BESS)\n- **Característica especial — Thermal Runaway:**\n  - Reação exotérmica autossustentada interna\n  - Gera calor + gases inflamáveis + flamejamento\n  - **Pode reiniciar horas ou dias após aparente extinção**\n  - Temperatura pode ultrapassar 600°C\n- **Extinção:** resfriamento intenso e prolongado com **água em grande volume**\n  - Nunca CO₂ (não resfria suficientemente)\n  - Nunca pó ABC (não penetra na célula)\n- **EPI mínimo:** luvas resistentes a corte/calor, óculos de proteção, máscara com filtro para gases ácidos\n- **Após extinção:** manter vigilância por no mínimo 24h; não descartar em lixo comum\n- **Exemplo na empresa:** sala de TI, veículos da frota EV, nobreaks, celulares carregando\n\n> 🔴 **Atenção:** incêndios Classe L com baterias grandes (EV, BESS) **não são combatíveis pelo brigadista orgânico** — acionar 193 e evacuar a área."},"recurso":{"titulo":"Etapa 3 — Vídeo / Recurso Prático (15 min)","corpo_md":"**Opção A — Vídeo:**\nBuscar no YouTube: *\"Classes de incêndio Bombeiros\"* ou *\"Classe L lítio incêndio\"*\n\n**Opção B — Jogo de identificação (dinâmica):**\nO instrutor cita um cenário; os alunos levantam um cartão com a letra da classe correta.\n\n| Cenário | Classe correta |\n|---------|---------------|\n| Arquivo de papel pegando fogo | A |\n| Vazamento de GLP com chamas | B |\n| Computador em chamas sem desligar da tomada | C |\n| Fritadeira com óleo em chamas | K |\n| Bateria de notebook em thermal runaway | L |\n| Pó de magnésio em chamas na oficina | D |\n\n*Fabricar cartões A/B/C/D/K/L em papel ou papelão antes da aula.*"},"verificacao":{"titulo":"Etapa 4 — Verificação de Aprendizagem (5 min)","evidencia":"Evidência documental: registrar nome do aluno e respostas.","questoes":[{"pergunta":"Um princípio de incêndio começa em um servidor de TI que ainda está ligado na tomada. Qual classe é essa e o que NÃO usar?","opcoes":[{"texto":"Classe A — não usar CO₂","correta":false},{"texto":"Classe C — não usar água nem espuma","correta":true},{"texto":"Classe B — não usar pó","correta":false},{"texto":"Classe K — não usar água","correta":false}]},{"pergunta":"O que caracteriza a Classe L (lítio) e a diferencia das demais?","opcoes":[{"texto":"Queima em profundidade como sólido comum","correta":false},{"texto":"Pode reiniciar horas após a extinção por thermal runaway","correta":true},{"texto":"Reage com água formando sabão (saponificação)","correta":false},{"texto":"É extinta facilmente com CO₂","correta":false}]},{"pergunta":"Incêndio em fritadeira industrial com óleo vegetal. Qual extintor usar?","opcoes":[{"texto":"Água pressurizada","correta":false},{"texto":"Pó ABC","correta":false},{"texto":"CO₂","correta":false},{"texto":"Extintor classe K (agente úmido)","correta":true}]},{"pergunta":"Qual classe de incêndio envolve metais pirofóricos como magnésio e sódio?","opcoes":[{"texto":"Classe A","correta":false},{"texto":"Classe B","correta":false},{"texto":"Classe D","correta":true},{"texto":"Classe L","correta":false}]},{"pergunta":"Ao listar corretamente todas as classes de incêndio segundo a IN 28/2024, devemos incluir:","opcoes":[{"texto":"A, B, C e D apenas","correta":false},{"texto":"A, B, C, D e K","correta":false},{"texto":"A, B, C, D, K e L","correta":true},{"texto":"A, B e C apenas","correta":false}]}]},"fechamento":{"titulo":"Etapa 5 — Fechamento (2 min)","pontos_chave":["6 classes, 6 riscos diferentes — A, B, C, D, K e L; cada uma exige abordagem específica","Água é inimiga da Classe C (choque), K (explosão de vapor) e D (reação violenta)","Classe L (lítio) é a mais traiçoeira — thermal runaway pode reiniciar; chamar 193 em baterias grandes"],"ponte":"Agora sabemos identificar o tipo de incêndio. No próximo componente vamos entender quais agentes extintores existem, como eles funcionam e os métodos de extinção para cada situação — isso vai dar sentido completo ao uso correto do extintor."}}$json1$::jsonb where name = 'B2 — Classes de Incêndio (A, B, C, D, K e L)';
update public.subthemes set conteudo = $json2${"duracao":"1h","norma":"IN 28/2024 CBMSC | NBR 14276 Anexo B","modulo":"Noções de Extinção","contexto":{"titulo":"Etapa 1 — Contexto (5 min)","corpo_md":"**Dado de abertura:**\nExtintores vencidos ou com agente inadequado são encontrados em mais de 30% das empresas auditadas pelo CBMSC em SC. Um extintor de CO₂ usado em um incêndio de classe A (sólido) apaga as chamas, mas a brasa continua ativa e o fogo relampeja minutos depois.\n\n**Pergunta disparadora:**\n> \"Vocês sabem quantos tipos de extintor existem neste prédio? E por que são diferentes?\""},"explicacao":{"titulo":"Etapa 2 — Explicação (35 min)","corpo_md":"### 2.1 Métodos de Extinção (os 4 princípios)\n\n| Método | Como age | Remove do tetraedro |\n|--------|----------|---------------------|\n| **Resfriamento** | Reduz temperatura abaixo do ponto de ignição | Calor |\n| **Abafamento** | Impede contato com O₂ | Comburente |\n| **Isolamento** | Remove o combustível do fogo | Combustível |\n| **Inibição química** | Interrompe a reação em cadeia | Reação em cadeia |\n\n### 2.2 Agentes Extintores\n\n#### Água\n- **Ação:** resfriamento (principal) + abafamento (vapor d'água)\n- **Classes:** A ✅ | B ❌ | C ❌ (condutor) | D ❌ (reação) | K ❌ (explosão vapor) | L ✅ (em volume, para resfriamento prolongado)\n- **Formas:** pressurizada (cilindro), névoa (sprinkler), hidrante\n- **Atenção:** água nunca deve ser aplicada em equipamentos elétricos energizados\n\n#### Espuma Mecânica\n- **Ação:** abafamento (camada sobre o líquido) + resfriamento\n- **Classes:** A ✅ | B ✅ | C ❌ | D ❌ | K ❌ | L ❌\n- **Uso típico:** depósitos de combustível, postos de gasolina, hangares\n\n#### Dióxido de Carbono — CO₂\n- **Ação:** abafamento (desloca O₂) + leve resfriamento\n- **Classes:** A ⚠️ (superficial) | B ✅ | C ✅ | D ❌ | K ❌ | L ❌\n- **Vantagem:** não deixa resíduo (uso em salas de servidores, equipamentos sensíveis)\n- **Atenção:** em espaços confinados, pode causar asfixia; não segurar pelo cilindro (congelamento)\n\n#### Pó Químico Seco BC\n- **Ação:** inibição química da reação em cadeia\n- **Classes:** A ❌ | B ✅ | C ✅ | D ❌ | K ❌ | L ❌\n- **Composição:** bicarbonato de sódio ou potássio\n- **Resíduo:** corrosivo para equipamentos elétricos; dificulta visibilidade\n\n#### Pó Químico Seco ABC (ou Pó Multipropósito)\n- **Ação:** inibição química + abafamento (sinterização em classe A)\n- **Classes:** A ✅ | B ✅ | C ✅ | D ❌ | K ❌ | L ❌\n- **Composição:** fosfato de amônio monobase\n- **O mais comum em empresas** — extintor vermelho com o rótulo ABC\n\n#### Agente Úmido — Classe K\n- **Ação:** saponificação (reação química com a gordura, forma uma camada sólida) + resfriamento\n- **Classes:** K ✅ (exclusivo para óleos e gorduras)\n- **Uso típico:** cozinhas industriais, fritadeiras, coifas\n\n#### Pó Especial — Classe D\n- **Ação:** abafamento por formação de crosta sobre o metal\n- **Classes:** D ✅ (exclusivo para metais pirofóricos)\n- **Composição:** grafite, cloreto de sódio, areia seca (dependendo do metal)\n- **Nunca usar** água, CO₂, espuma ou pó ABC em metais — reação explosiva\n\n### 2.3 Tabela-Resumo: Agente × Classe\n\n| Agente | A | B | C | D | K | L |\n|--------|---|---|---|---|---|---|\n| Água pressurizada | ✅ | ❌ | ❌ | ❌ | ❌ | ✅* |\n| Espuma mecânica | ✅ | ✅ | ❌ | ❌ | ❌ | ❌ |\n| CO₂ | ⚠️ | ✅ | ✅ | ❌ | ❌ | ❌ |\n| Pó BC | ❌ | ✅ | ✅ | ❌ | ❌ | ❌ |\n| Pó ABC | ✅ | ✅ | ✅ | ❌ | ❌ | ❌ |\n| Agente úmido K | ❌ | ❌ | ❌ | ❌ | ✅ | ❌ |\n| Pó especial D | ❌ | ❌ | ❌ | ✅ | ❌ | ❌ |\n\n*\\*Água para Classe L: em grande volume e de forma prolongada; não aplica extintores portáteis padrão.*\n\n### 2.4 Como Usar um Extintor — Técnica PASS\n\n> Válido para extintores portáteis (pó ABC, CO₂, espuma):\n\n**P** — **Puxe** o pino de segurança (lacre)\n**A** — **Aponte** o bico/mangueira para a **base** das chamas (não para as chamas)\n**P** — **Pressione** o gatilho/manete\n**A** — **Avance** em varredura (movimentos de lado a lado, da frente para dentro)\n\n**Distâncias de segurança:**\n- Pó ABC: 2–4 metros\n- CO₂: 1–2 metros (corrente de descarga pode espalhar líquidos inflamáveis)\n- Água: 3–5 metros\n\n**Regra de saída:** posicione-se sempre entre o fogo e a saída. Se o extintor acabar e o fogo persistir: abandone e acione 193."},"recurso":{"titulo":"Etapa 3 — Vídeo / Recurso Prático (15 min)","corpo_md":"**Opção A — Vídeo:**\nBuscar no YouTube: *\"Como usar extintor de incêndio\"* — canal CBMSC, SENAI ou SESI.\n\n**Opção B — Simulação visual:**\nMontar no quadro: 4 cartões com cenários de incêndio. Alunos escolhem o agente correto e justificam.\n\n| Cenário | Agente correto | Por quê |\n|---------|---------------|---------|\n| Papel em chamas em sala sem equipamentos | Pó ABC ou Água | Classe A, resfriamento ou inibição |\n| Servidor de TI ligado em chamas | CO₂ | Classe C, não condutor, sem resíduo |\n| Cozinha: fritadeira em chamas | Agente úmido K | Saponificação, água causaria explosão |\n| Bateria de notebook em thermal runaway | Água em volume | Resfriamento prolongado — chamar 193 |"},"verificacao":{"titulo":"Etapa 4 — Verificação de Aprendizagem (5 min)","evidencia":"Evidência documental: registrar nome e respostas.","questoes":[{"pergunta":"Qual método de extinção remove o CALOR do tetraedro do fogo?","opcoes":[{"texto":"Abafamento","correta":false},{"texto":"Inibição química","correta":false},{"texto":"Resfriamento","correta":true},{"texto":"Isolamento","correta":false}]},{"pergunta":"O extintor de CO₂ é indicado para a Classe C porque:","opcoes":[{"texto":"Resfria profundamente o equipamento","correta":false},{"texto":"É um agente não condutor de eletricidade e não deixa resíduo","correta":true},{"texto":"Reage quimicamente com o plástico para apagar","correta":false},{"texto":"Tem alta pressão que abafa as chamas","correta":false}]},{"pergunta":"A técnica PASS indica que o bico do extintor deve ser apontado para:","opcoes":[{"texto":"As chamas (topo do fogo)","correta":false},{"texto":"O ar ao redor do fogo","correta":false},{"texto":"A base das chamas","correta":true},{"texto":"O teto do ambiente","correta":false}]},{"pergunta":"Para um incêndio em depósito de gasolina (Classe B), qual agente está CORRETO?","opcoes":[{"texto":"Água pressurizada","correta":false},{"texto":"Espuma mecânica","correta":true},{"texto":"Pó especial D","correta":false},{"texto":"Agente úmido K","correta":false}]},{"pergunta":"Se o extintor acabar e o fogo ainda estiver ativo, o brigadista orgânico deve:","opcoes":[{"texto":"Procurar outro extintor e continuar","correta":false},{"texto":"Usar água como alternativa","correta":false},{"texto":"Abandonar o local e acionar 193","correta":true},{"texto":"Aguardar os bombeiros no local do fogo","correta":false}]}]},"fechamento":{"titulo":"Etapa 5 — Fechamento (2 min)","pontos_chave":["Cada agente tem classes permitidas e proibidas — erro na escolha pode agravar o incêndio","Técnica PASS: Puxe o pino · Aponte na base · Pressione o gatilho · Avance em varredura","Extintor vazio + fogo ativo = abandono imediato — nunca arriscar além da capacidade do equipamento"],"ponte":"Agora sabemos combater o fogo. Mas e quando há vítimas? O próximo módulo é Primeiros Socorros, e começamos com o mais básico: como avaliar uma cena de emergência com segurança e quando acionar o 193."}}$json2$::jsonb where name = 'B3 — Agentes e Métodos de Extinção';
update public.subthemes set conteudo = $json3${"duracao":"1h","norma":"IN 28/2024 CBMSC | NBR 14276 Anexo B","modulo":"Primeiros Socorros","contexto":{"titulo":"Etapa 1 — Contexto (5 min)","corpo_md":"**Caso real:**\nEm uma fábrica têxtil de SC, um funcionário encontrou um colega inconsciente próximo a uma máquina em operação. Ao tentar socorrer sem verificar a cena, levou um choque elétrico e também ficou inconsciente — gerando duas vítimas.\n\n**Princípio fundamental:**\n> Um socorrista que vira vítima piora a cena. A segurança do brigadista orgânico é a primeira prioridade.\n\n**Números de emergência (fixar no quadro):**\n| Número | Serviço |\n|--------|---------|\n| **193** | Corpo de Bombeiros CBMSC |\n| **192** | SAMU |\n| **190** | Polícia Militar |"},"explicacao":{"titulo":"Etapa 2 — Explicação (35 min)","corpo_md":"### 2.1 Sequência de Avaliação da Cena (CENA → VÍTIMA)\n\n#### Passo 1 — Segurança da Cena\n\nAntes de aproximar, perguntar mentalmente:\n- **Há risco para mim?** (fogo ativo, gás, eletricidade, estrutura instável, trânsito)\n- **O risco pode ser eliminado?** (desligar energia, remover do local, isolar a área)\n- **Se não for seguro → não entre.** Acione 193 e aguarde.\n\nSinais de cena insegura: fumaça densa, cheiro de gás, fios expostos, barulho de estrutura cedendo, líquidos desconhecidos.\n\n#### Passo 2 — Número de Vítimas e Mecanismo de Lesão\n\nAo se aproximar com segurança:\n- Contar as vítimas visíveis\n- Identificar o **mecanismo de lesão**: queda de altura, esmagamento, queimadura, inalação de fumaça, choque elétrico\n- O mecanismo indica as lesões prováveis que o SAMU/Bombeiros precisam saber\n\n#### Passo 3 — Acionamento Precoce — ligue 193 ANTES de socorrer\n\nAo encontrar qualquer vítima inconsciente ou situação grave:\n- **Ligue 193 imediatamente** (ou mande alguém ligar enquanto você avalia)\n- Informar: **localização exata** (endereço, andar, setor) + **natureza da emergência** + **número de vítimas** + **condição** (consciente/inconsciente, respira/não respira)\n- **Não desligue antes que o atendente autorize**\n\n### 2.2 Avaliação Primária da Vítima (A-B-C simplificado)\n\nApós cena segura e 193 acionado:\n\n#### Nível de consciência — AVDI\n\n| Letra | Teste |\n|-------|-------|\n| **A** — Alerta | Está acordado e orienta-se normalmente? |\n| **V** — Verbal | Responde ao chamado (\"como você está?\") |\n| **D** — Doloroso | Reage a estímulo de dor (pressão no esterno) |\n| **I** — Irresponsivo | Sem resposta a nenhum estímulo |\n\n**Como avaliar:**\n1. Aproxime-se pela frente — \"Você está bem? Pode me ouvir?\"\n2. Segure os dois ombros suavemente e repita o chamado\n3. Se irresponsivo → iniciar protocolo de RCP (componente B5)\n\n#### Respiração — VOS (Ver, Ouvir, Sentir)\n\n- **Ver:** movimentação do tórax\n- **Ouvir:** fluxo de ar pela boca/nariz\n- **Sentir:** saída de ar no dorso da mão (não mais que 10 segundos)\n\n| Resultado | Ação |\n|-----------|------|\n| Respira normalmente | Posição lateral de segurança (se inconsciente e sem suspeita de trauma) |\n| Respiração agônica (gasping) | Tratar como parada respiratória |\n| Não respira | Iniciar RCP imediatamente |\n\n#### Posição Lateral de Segurança (PLS)\n\nIndicada quando: vítima inconsciente + respira + sem suspeita de lesão na coluna\n\nObjetivo: prevenir aspiração de vômito\n\n1. Ajoelhe-se ao lado da vítima\n2. Coloque o braço mais próximo em ângulo reto com o corpo\n3. Traga o braço oposto sobre o peito, segure a mão na bochecha\n4. Flexione a perna oposta; use-a para virar a vítima\n5. Ajuste o queixo para manter via aérea aberta\n6. Monitorar respiração continuamente até a chegada do socorro\n\n### 2.3 Anotações para Passagem de Caso ao SAMU/Bombeiros\n\nAo chegar o socorro, o brigadista orgânico deve informar:\n- O que aconteceu (mecanismo)\n- Hora do evento (estimada)\n- Nível de consciência inicial e atual\n- Respiração presente/ausente\n- Intervenções realizadas (RCP, compressão de ferida, etc.)"},"recurso":{"titulo":"Etapa 3 — Vídeo / Recurso Prático (15 min)","corpo_md":"**Opção A — Vídeo:**\nBuscar no YouTube: *\"Avaliação primária vítima Bombeiros\"* ou *\"Primeiros socorros avaliação de cena\"*\n\n**Opção B — Simulação de cena (dinâmica com 3 alunos):**\n\n*Cenário:* Colega encontrado no chão do depósito, próximo a um extintor vazio. Há cheiro de fumaça.\n\nPapéis:\n- Aluno A: brigadista que encontra a vítima\n- Aluno B: vítima (instrução secreta: irresponsivo, não respira)\n- Aluno C: observa e avalia\n\nO aluno A deve executar: verificar cena → acionar 193 (simulado) → AVDI → VOS → identificar necessidade de RCP\n\nDebriefe: o que foi feito certo? O que faltou?"},"verificacao":{"titulo":"Etapa 4 — Verificação de Aprendizagem (5 min)","evidencia":"Evidência documental: registrar nome e respostas.","questoes":[{"pergunta":"Ao encontrar uma vítima inconsciente, a PRIMEIRA ação do brigadista orgânico é:","opcoes":[{"texto":"Iniciar RCP imediatamente","correta":false},{"texto":"Gritar por ajuda","correta":false},{"texto":"Verificar a segurança da cena","correta":true},{"texto":"Ligar para o superior hierárquico","correta":false}]},{"pergunta":"O número de emergência do Corpo de Bombeiros CBMSC é:","opcoes":[{"texto":"192","correta":false},{"texto":"190","correta":false},{"texto":"193","correta":true},{"texto":"197","correta":false}]},{"pergunta":"A Posição Lateral de Segurança é indicada quando a vítima está:","opcoes":[{"texto":"Consciente e com dor no peito","correta":false},{"texto":"Inconsciente, respirando e sem suspeita de lesão na coluna","correta":true},{"texto":"Inconsciente e sem respiração","correta":false},{"texto":"Consciente com dificuldade para respirar","correta":false}]},{"pergunta":"No método AVDI, a letra \"D\" representa:","opcoes":[{"texto":"Drenagem — verificar hemorragias","correta":false},{"texto":"Doloroso — a vítima responde a estímulo de dor","correta":true},{"texto":"Diagnóstico — identificar a lesão principal","correta":false},{"texto":"Desmaio — vítima sem consciência","correta":false}]},{"pergunta":"Ao acionar o 193, qual informação é MAIS urgente de passar?","opcoes":[{"texto":"CPF e nome completo da vítima","correta":false},{"texto":"Histórico médico da vítima","correta":false},{"texto":"Localização exata + natureza da emergência + condição da vítima","correta":true},{"texto":"Nome do seguro de saúde da empresa","correta":false}]}]},"fechamento":{"titulo":"Etapa 5 — Fechamento (2 min)","pontos_chave":["Cena segura primeiro — socorrista que vira vítima piora tudo","193 precoce — ligue (ou mande alguém ligar) antes de iniciar qualquer manobra","AVDI + VOS em 10 segundos — inconsciente sem respiração = RCP imediata"],"ponte":"Agora sabemos avaliar a cena e chamar ajuda. Mas e enquanto o socorro não chega? No próximo componente aprenderemos as manobras que salvam vidas nos minutos críticos: RCP, uso do DEA e desobstrução de via aérea — o componente B5."}}$json3$::jsonb where name = 'B4 — Avaliação de Cena e Vítima + Acionamento 193';
update public.subthemes set conteudo = $json4${"duracao":"1h","norma":"IN 28/2024 CBMSC | NBR 14276 Anexo B | AHA Guidelines 2020","modulo":"Primeiros Socorros","contexto":{"titulo":"Etapa 1 — Contexto (5 min)","corpo_md":"**Dado de abertura:**\nA parada cardiorrespiratória (PCR) mata em 4–6 minutos por falta de oxigênio no cérebro. Para cada minuto sem RCP, a chance de sobrevivência cai 10%. Com RCP imediata + DEA em até 3 minutos, a sobrevivência pode chegar a 70%.\n\nNo Brasil, 70% das PCRs ocorrem fora de hospitais. O brigadista orgânico é estatisticamente o primeiro a estar presente.\n\n**Pergunta:**\n> \"Se um colega cair agora sem respiração, quantos minutos vocês têm para agir antes que o dano cerebral seja irreversível?\""},"explicacao":{"titulo":"Etapa 2 — Explicação (35 min)","corpo_md":"### 2.1 Reconhecer a PCR\n\nVítima em PCR:\n- Irresponsiva (não responde ao AVDI)\n- Sem respiração normal (ausente ou apenas gasping — respiração agônica)\n- Sem pulso (verificar apenas se treinado; em caso de dúvida, iniciar RCP)\n\n> ⚠️ Gasping (suspiro irregular) = tratar como sem respiração → iniciar RCP\n\n### 2.2 Sequência de Suporte Básico de Vida (SBV) — AHA 2020\n\n**C-A-B:** Compressões → Vias Aéreas → Ventilação\n\n#### Passo 1 — Chamar ajuda e ligar 193/192\n- Gritar por ajuda\n- Delegar: \"Você, ligue 193!\" / \"Você, traga o DEA!\"\n- Começar RCP sem aguardar socorro\n\n#### Passo 2 — Posicionamento\n- Vítima em decúbito dorsal (de costas) em superfície rígida\n- Brigadista ajoelhado ao lado do tórax\n\n#### Passo 3 — Compressões Torácicas\n\n| Parâmetro | Valor |\n|-----------|-------|\n| Frequência | 100–120 compressões/minuto |\n| Profundidade (adulto) | 5–6 cm |\n| Ponto de compressão | Centro do tórax (metade inferior do esterno) |\n| Posição das mãos | Sobrepostas, dedos entrelaçados, braços estendidos |\n| Retorno do tórax | Total após cada compressão — não apoiar o peso |\n| Interrupções | Mínimas — máx. 10 segundos |\n\n**Ritmo de referência:** música \"Stayin' Alive\" (Bee Gees) — ~103 BPM\n\n#### Passo 4 — Abertura da Via Aérea\nApós 30 compressões:\n- Inclinação da cabeça + elevação do queixo (head-tilt, chin-lift)\n- Em suspeita de trauma cervical: apenas elevação da mandíbula\n\n#### Passo 5 — Ventilações\n- 2 ventilações de resgate\n- Cada ventilação: 1 segundo, observar expansão do tórax\n- Relação: **30:2** (30 compressões : 2 ventilações)\n\n> ⚠️ Se não souber/quiser ventilar: RCP apenas com compressões (hands-only CPR) — ainda é eficaz nos primeiros minutos.\n\n#### Quando parar a RCP\n- DEA instalado e pronto para análise\n- Chegada do socorro avançado (SAMU/Bombeiros)\n- Cena se torna insegura\n- Exaustão física completa (revezar a cada 2 minutos se houver mais socorristas)\n\n---\n\n### 2.3 DEA — Desfibrilador Externo Automático\n\n> Nota: Quando o imóvel exigir DEA (art. 34 IN 28/2024), o uso do DEA integra obrigatoriamente o conteúdo de APH.\n\n**O DEA é um equipamento guiado por voz** — faz tudo que o operador precisa fazer.\n\n#### Sequência de uso:\n\n**1. Ligar o DEA** — botão on/off ou abrir a tampa (alguns modelos ligam automaticamente)\n\n**2. Fixar os eletrodos** — seguir os desenhos na embalagem:\n- Eletrodo 1: abaixo da clavícula direita\n- Eletrodo 2: lateral esquerda, abaixo da axila (linha da mama)\n- Pele seca e limpa (remover objetos metálicos, sutiã com aro, marcar com caneta a posição se necessário)\n\n**3. Analisar o ritmo** — afastar TODOS da vítima (\"Ninguém toca!\")\n- DEA analisa sozinho (~5–10 segundos)\n- Resultado: choque indicado OU choque não indicado\n\n**4. Se choque indicado:**\n- Confirmar que ninguém está tocando\n- Pressionar o botão de choque\n- Retomar RCP imediatamente após o choque (não aguardar resposta)\n\n**5. Se choque não indicado:**\n- Retomar RCP imediatamente\n- DEA reavalia a cada 2 minutos\n\n> O DEA não vai machucar uma vítima que não precisa do choque — é seguro usar.\n\n---\n\n### 2.4 OVACE — Obstrução de Via Aérea por Corpo Estranho\n\n#### Reconhecimento\n\n| Sinal | O que observar |\n|-------|---------------|\n| Tosse eficaz | Vítima tosse com força — NÃO intervir, estimular a tossir |\n| Tosse ineficaz | Tosse fraca, engasgado, não consegue falar nem respirar |\n| Silêncio total | Via aérea totalmente bloqueada — risco imediato de vida |\n\n#### OVACE em Adulto Consciente — Manobra de Heimlich\n\n1. Posicionar-se atrás da vítima\n2. Uma perna entre as pernas da vítima (base estável)\n3. Punho fechado, posicionado 2 dedos acima do umbigo (região epigástrica)\n4. Outra mão sobre o punho\n5. Aplicar pressões para dentro e para cima — repetir até desobstruir ou vítima perder consciência\n\n**Se perder a consciência:** deitar no chão, ligar 193, iniciar RCP. A cada ciclo de compressões, verificar via aérea antes de ventilar.\n\n#### OVACE em Lactente (< 1 ano)\n\n- **Nunca Heimlich em bebê**\n- **5 golpes nas costas** (entre as escápulas, calcanhar da mão)\n- **5 compressões torácicas** (dois dedos, centro do tórax)\n- Alternar até desobstruir ou vítima ficar inconsciente\n\n#### OVACE em Gestante ou Obeso\n\n- Substituir compressões abdominais por compressões torácicas (centro do esterno)\n- Mesma lógica: 5 compressões torácicas por trás"},"recurso":{"titulo":"Etapa 3 — Vídeo / Recurso Prático (15 min)","corpo_md":"**Opção A — Vídeo:**\nBuscar: *\"RCP DEA primeiros socorros\"* — AHA Brasil, CBMSC ou Sociedade Brasileira de Cardiologia.\n\n**Opção B — Prática no manequim (se disponível):**\n- Demonstrar 30:2 no manequim\n- Alunos revezam 2 minutos cada\n- Correção de postura, profundidade e ritmo\n- Se houver DEA de treinamento: simular sequência completa\n\n**Opção C — Simulação sem manequim:**\nUsar travesseiro firme sobre uma cadeira. Alunos praticam posicionamento de mãos e aplicam pressão visual (sem força total). Foco em ritmo e postura."},"verificacao":{"titulo":"Etapa 4 — Verificação de Aprendizagem (5 min)","evidencia":"Evidência documental: registrar nome e respostas.","questoes":[{"pergunta":"A frequência correta de compressões torácicas em adulto é:","opcoes":[{"texto":"60–80 por minuto","correta":false},{"texto":"80–100 por minuto","correta":false},{"texto":"100–120 por minuto","correta":true},{"texto":"Mais de 120 por minuto","correta":false}]},{"pergunta":"Ao usar o DEA, no momento da análise do ritmo cardíaco, o brigadista orgânico deve:","opcoes":[{"texto":"Continuar as compressões para não interromper o fluxo sanguíneo","correta":false},{"texto":"Afastar todos da vítima","correta":true},{"texto":"Iniciar as ventilações","correta":false},{"texto":"Verificar o pulso carotídeo","correta":false}]},{"pergunta":"A manobra de Heimlich em adulto consciente com OVACE aplica pressão:","opcoes":[{"texto":"No pescoço da vítima","correta":false},{"texto":"No centro do tórax","correta":false},{"texto":"Na região epigástrica (entre o umbigo e o esterno), para dentro e para cima","correta":true},{"texto":"Nas costas, com golpes secos","correta":false}]},{"pergunta":"Um colega está engasgado mas ainda consegue tossir com força. O que fazer?","opcoes":[{"texto":"Iniciar Heimlich imediatamente","correta":false},{"texto":"Chamar 193 e aguardar","correta":false},{"texto":"Estimular a vítima a continuar tossindo — não intervir ainda","correta":true},{"texto":"Deitar a vítima no chão e iniciar RCP","correta":false}]},{"pergunta":"Na relação compressão-ventilação do SBV para adulto, o padrão é:","opcoes":[{"texto":"15:2","correta":false},{"texto":"30:2","correta":true},{"texto":"20:1","correta":false},{"texto":"5:1","correta":false}]}]},"fechamento":{"titulo":"Etapa 5 — Fechamento (2 min)","pontos_chave":["Cada minuto sem RCP = -10% de chance de sobrevivência — comece imediatamente","DEA é seguro e guiado por voz — ligue, cole os eletrodos, afaste todos, siga as instruções","OVACE: tosse eficaz → não interfira; tosse ineficaz → Heimlich; inconsciente → RCP"],"ponte":"Salvamos a vida com RCP e DEA. Mas emergências no trabalho também incluem hemorragias, queimaduras e crises clínicas. No B6 vamos aprender a controlar hemorragias, tratar queimaduras corretamente e reconhecer quando uma crise clínica exige o 193."}}$json4$::jsonb where name = 'B5 — RCP, DEA e OVACE';
update public.subthemes set conteudo = $json5${"duracao":"1h","norma":"IN 28/2024 CBMSC | NBR 14276 Anexo B","modulo":"Primeiros Socorros","contexto":{"titulo":"Etapa 1 — Contexto (5 min)","corpo_md":"**Dado de abertura:**\nHemorragias traumáticas são a principal causa de morte evitável no trauma — 40% das mortes por acidente de trabalho poderiam ser evitadas com controle hemorrágico precoce. Queimaduras de grau 2 extensas causam choque hipovolêmico em menos de 1 hora sem tratamento.\n\n**Pergunta:**\n> \"Qual é a primeira coisa que vocês fariam se um colega cortasse a mão numa máquina e começasse a sangrar muito?\""},"explicacao":{"titulo":"Etapa 2 — Explicação (35 min)","corpo_md":"### 2.1 Hemorragias\n\n#### Tipos por origem\n\n| Tipo | Característica | Gravidade |\n|------|---------------|-----------|\n| Arterial | Sangue vermelho-vivo, pulsátil | Alta |\n| Venosa | Sangue vermelho-escuro, fluxo contínuo | Moderada a alta |\n| Capilar | Sangramento superficial difuso | Baixa |\n\n#### Controle Hemorrágico — Sequência STOP\n\n**1. Compressão Direta** — SEMPRE o primeiro passo\n- Comprimir firmemente com pano limpo, gaze ou a própria mão luva\n- Manter pressão constante por no mínimo 5–10 minutos\n- **Nunca retirar o curativo** — se sangrar, adicionar por cima\n- Se disponível: curativo hemostático (Combat Gauze) para feridas profundas\n\n**2. Elevação do Membro** (se não houver suspeita de fratura)\n- Elevar o membro acima do nível do coração\n- Reduz pressão de perfusão e auxilia na coagulação\n\n**3. Torniquete** — apenas se hemorragia não controlada por compressão + membro\n- Posicionar 5–7 cm acima da ferida\n- Apertar até o sangramento parar\n- Anotar hora de aplicação (no próprio torniquete ou na testa da vítima)\n- **Nunca remover após aplicado** — aguardar socorro avançado\n- Tempo máximo recomendado: 2h (acima disso, risco de dano tissular)\n\n#### Sinais de Choque Hipovolêmico\n- Pele pálida, fria e úmida\n- Pulso rápido e fraco\n- Sede intensa\n- Ansiedade e agitação\n- Confusão mental → perda de consciência (estágio grave)\n\n**Conduta:** deitar, elevar membros inferiores (se sem trauma), aquecer, acionar 193.\n\n---\n\n### 2.2 Queimaduras\n\n#### Classificação por Grau\n\n| Grau | Profundidade | Aspecto | Dor |\n|------|-------------|---------|-----|\n| 1º | Epiderme | Vermelhidão, sem bolha | Sim |\n| 2º superficial | Derme superficial | Bolhas, base rosada | Intensa |\n| 2º profundo | Derme profunda | Bolhas, base esbranquiçada | Reduzida |\n| 3º | Subcutâneo/músculo | Escura, coriácea, sem bolha | Ausente (nervo destruído) |\n\n#### Regra dos 9 — Extensão (adulto)\n\n| Região | % SCT |\n|--------|-------|\n| Cabeça e pescoço | 9% |\n| Cada braço | 9% |\n| Tronco anterior | 18% |\n| Tronco posterior | 18% |\n| Cada perna | 18% |\n| Períneo | 1% |\n\n> Queimadura > 10% SCT em adulto = risco de choque → acionar 193.\n\n#### Conduta nas Queimaduras\n\n**O que FAZER:**\n- Resfriar com água corrente morna (não gelada) por 10–20 minutos\n- Retirar roupas e acessórios NÃO aderidos\n- Cobrir com pano limpo úmido ou curativo não aderente\n- Manter a vítima aquecida (queimados perdem calor rapidamente)\n- Acionar 193 para queimaduras de 2º/3º grau ou extensas\n\n**O que NÃO fazer:**\n- ❌ Pasta de dente, manteiga, mel, clara de ovo — causam infecção\n- ❌ Estourar bolhas — barreira protetora\n- ❌ Retirar tecidos aderidos à pele\n- ❌ Cobrir com algodão (adere à ferida)\n- ❌ Água gelada ou gelo (vasoconstrição, piora a lesão)\n\n#### Queimaduras Especiais — Acionamento 193 sempre\n- Queimaduras no rosto, pescoço, mãos, genitais, pés, articulações\n- Inalação de fumaça (queimadura de via aérea — piora em horas)\n- Queimaduras elétricas (a entrada é pequena; a saída pode ser extensa)\n- Queimaduras químicas (neutralizar produto se seguro; lavar copiosamente)\n\n---\n\n### 2.3 Emergências Clínicas\n\n#### AVC — Protocolo FAST\n\n| Letra | Teste | Sinal positivo |\n|-------|-------|---------------|\n| **F** — Face | \"Sorria para mim\" | Um lado cai |\n| **A** — Arms (Braços) | \"Levante os dois braços\" | Um cai |\n| **S** — Speech (Fala) | \"Diga uma frase simples\" | Voz alterada ou não fala |\n| **T** — Time | — | Anotar hora dos sintomas → acionar 192 |\n\n> AVC é emergência tempo-dependente. \"Tempo é cérebro.\"\n\n#### Crise Hipoglicêmica (Açúcar Baixo)\n\n**Sinais:** tremor, sudorese, confusão, agressividade, perda de consciência\n- Vítima consciente e consegue engolir: oferecer açúcar, suco, refrigerante\n- Vítima inconsciente: **não oferecer nada pela boca** — acionar 192\n\n#### Convulsão\n\n**Durante a crise:**\n- Não segurar a vítima (risco de fratura)\n- Afastar objetos ao redor\n- Proteger a cabeça com objeto macio\n- Não colocar nada na boca\n\n**Após a crise:**\n- Posição lateral de segurança\n- Acionar 192 se: primeira convulsão, duração > 5 min, não acorda\n\n#### Crise Hipertensiva\n\n**Sinais:** cefaleia intensa de início súbito, visão turva, náuseas, zumbido\n- Sentar a vítima\n- Ambiente calmo e silencioso\n- Acionar 192\n- **Não dar medicamento** sem orientação médica"},"recurso":{"titulo":"Etapa 3 — Vídeo / Recurso Prático (15 min)","corpo_md":"**Opção A — Vídeo:**\nBuscar: *\"Controle de hemorragia torniquete\"* ou *\"FAST AVC\"* — SAMU ou hospital referência.\n\n**Opção B — Estações práticas (3 grupos rotativos de 5 min cada):**\n\n| Estação | Tema | Material |\n|---------|------|---------|\n| 1 | Compressão direta e torniquete improvisado | Faixa de tecido, luvas |\n| 2 — | Conduta em queimadura (o que fazer/não fazer) | Cartões cenário |\n| 3 | Protocolo FAST para AVC | Par de alunos testando entre si |"},"verificacao":{"titulo":"Etapa 4 — Verificação de Aprendizagem (5 min)","evidencia":"Evidência documental: registrar nome e respostas.","questoes":[{"pergunta":"O torniquete deve ser posicionado:","opcoes":[{"texto":"Diretamente sobre a ferida","correta":false},{"texto":"5–7 cm ACIMA da ferida","correta":true},{"texto":"Abaixo da ferida para conter o sangramento","correta":false},{"texto":"No pescoço para controlar hemorragias cervicais","correta":false}]},{"pergunta":"Para resfriar uma queimadura, a água correta é:","opcoes":[{"texto":"Água gelada por 5 minutos","correta":false},{"texto":"Gelo diretamente na lesão","correta":false},{"texto":"Água corrente morna por 10–20 minutos","correta":true},{"texto":"Água com sal para desinfectar","correta":false}]},{"pergunta":"No protocolo FAST para AVC, a letra \"T\" significa:","opcoes":[{"texto":"Temperatura — verificar febre","correta":false},{"texto":"Torniquete — controlar hemorragia cerebral","correta":false},{"texto":"Time — anotar hora dos sintomas e acionar socorro imediatamente","correta":true},{"texto":"Tórax — verificar respiração","correta":false}]},{"pergunta":"Durante uma convulsão, o brigadista orgânico deve:","opcoes":[{"texto":"Segurar firmemente a vítima para evitar movimentos","correta":false},{"texto":"Colocar um objeto na boca para proteger a língua","correta":false},{"texto":"Afastar objetos, proteger a cabeça e aguardar o fim da crise","correta":true},{"texto":"Aplicar água fria no rosto para interromper a crise","correta":false}]},{"pergunta":"Queimadura elétrica com ponto de entrada pequeno deve ser tratada como:","opcoes":[{"texto":"Queimadura leve de 1º grau, sem necessidade de socorro","correta":false},{"texto":"Emergência grave — acionar 193, pois o dano interno pode ser extenso","correta":true},{"texto":"Queimadura de 2º grau, tratar localmente com curativo","correta":false},{"texto":"Situação não coberta pelo protocolo de brigadista orgânico","correta":false}]}]},"fechamento":{"titulo":"Etapa 5 — Fechamento (2 min)","pontos_chave":["Hemorragia: compressão direta primeiro; torniquete só quando indispensável; anotar hora","Queimadura: água corrente morna por 10–20 min; nunca pasta de dente, gelo ou manteiga","Clínicas: FAST para AVC; açúcar para hipoglicemia consciente; não medicar sem orientação"],"ponte":"Terminamos o módulo de Primeiros Socorros. Agora entramos no terceiro e último módulo do Básico: os Sistemas Preventivos. No B7 vamos conhecer os equipamentos que a norma exige no seu local de trabalho — extintores, hidrantes e sinalização."}}$json5$::jsonb where name = 'B6 — Hemorragias, Queimaduras e Emergências Clínicas';
update public.subthemes set conteudo = $json6${"duracao":"45min","norma":"IN 28/2024 CBMSC | NBR 12693 | NBR 13714 | NBR 13434","modulo":"Sistemas Preventivos","contexto":{"titulo":"Etapa 1 — Contexto (5 min)","corpo_md":"**Dado de abertura:**\nDurante vistoria do CBMSC, os três problemas mais frequentes são: extintores vencidos ou com carga inadequada, hidrantes sem mangueira ou pressão, e sinalização de saída de emergência ausente ou obstruída. São infrações que podem resultar em embargo do estabelecimento.\n\n**Questão motivadora:**\n> \"Alguém sabe onde estão os extintores neste prédio? Alguém já verificou a validade?\""},"explicacao":{"titulo":"Etapa 2 — Explicação (25 min)","corpo_md":"### 2.1 Extintores de Incêndio (NBR 12693)\n\n#### Componentes do extintor\n\n- **Cilindro:** corpo pressurizado\n- **Manômetro:** indica a pressão (verde = operacional; vermelho = recarga necessária)\n- **Pino de segurança:** trava o gatilho\n- **Gatilho/manete:** aciona a descarga\n- **Mangueira/bico:** direciona o agente\n- **Lacre:** comprova que não foi usado\n- **Rótulo:** classe, agente, validade da recarga\n\n#### Tipos e identificação\n\n| Tipo | Cor padrão (corpo/faixa) | Agente | Classes |\n|------|--------------------------|--------|---------|\n| Água pressurizada | Vermelho | Água | A |\n| Pó ABC | Vermelho | Fosfato de amônio | A, B, C |\n| CO₂ | Vermelho + faixa amarela | Dióxido de carbono | B, C |\n| Pó BC | Vermelho + faixa amarela | Bicarbonato | B, C |\n| Espuma | Vermelho + faixa verde | Espuma AFFF | A, B |\n| Agente úmido | Vermelho + faixa bege | Acetato de potássio | K |\n\n#### Manutenção e validade (NBR 12693)\n- Inspeção visual: **mensal** (pelo brigadista orgânico ou responsável)\n- Manutenção: **anual** (empresa habilitada)\n- Recarga: após uso ou conforme laudo técnico\n- Peso do cilindro e pressão devem ser verificados no rótulo\n\n#### Localização e acessibilidade\n- Altura máxima do manômetro: 1,60m do piso\n- Desobstruído — nunca trancado, bloqueado ou atrás de porta\n- Distância máxima a percorrer: conforme NBR 12693 (ex: 15m para risco médio)\n- Identificado com placa de sinalização (NBR 13434)\n\n---\n\n### 2.2 Sistema de Hidrantes (NBR 13714)\n\n#### Componentes\n- **Abrigo de hidrante:** caixa de parede com mangueira, esguicho e registro\n- **Mangueira de incêndio:** 15m, 20m ou 30m de comprimento; 1½\" ou 2½\"\n- **Esguicho:** regulável (jato pleno ou neblina)\n- **Registro de gaveta:** abre o fluxo de água da rede\n\n#### Como operar (nível básico — somente com treinamento prático)\n1. Abrir o abrigo\n2. Desenrolar a mangueira completamente (evitar nós)\n3. Acoplar esguicho na ponta\n4. Um brigadista segura o esguicho, posicionado para ataque\n5. Outro abre o registro lentamente (pressão súbita derruba o operador)\n6. Atacar pela base das chamas; nunca entrar em ambiente com fumaça densa\n\n> ⚠️ No Básico, a operação de hidrantes é **teórica**. A prática ocorre no Avançado (A7).\n\n#### Manutenção\n- Inspeção semestral da rede e pressão\n- Mangueiras: secas, enroladas, sem dobras permanentes\n- Esguichos: vedações íntegras\n\n---\n\n### 2.3 Sinalização de Segurança Contra Incêndio (NBR 13434)\n\n#### Categorias de sinalização\n\n| Categoria | Função | Cor |\n|-----------|--------|-----|\n| **Proibição** | Proibir ações que geram risco | Vermelho/branco |\n| **Alerta** | Indicar materiais/áreas perigosas | Amarelo/preto |\n| **Orientação e salvamento** | Rotas de fuga, saídas, primeiros socorros | Verde/branco |\n| **Equipamentos de combate** | Localização de extintores, hidrantes | Vermelho/branco |\n\n#### Sinais mais importantes para o brigadista orgânico\n\n- **Saída de emergência** — seta verde com seta ou figura humana\n- **Extintor** — placa vermelha com ícone de extintor\n- **Hidrante** — placa vermelha com ícone de torneira/mangueira\n- **Ponto de encontro** — placa verde com grupo de pessoas\n- **Não obstrua** — esta saída deve permanecer desobstruída\n\n#### Regras de posicionamento\n- Visível a no mínimo 30m de distância\n- Em locais com fumaça: sinalização complementar próxima ao piso\n- Nunca cobrir com cartazes, prateleiras ou pinturas"},"recurso":{"titulo":"Etapa 3 — Vídeo / Recurso Prático (10 min)","corpo_md":"**Opção A — Vídeo:**\nBuscar: *\"Sistema de hidrantes funcionamento\"* ou *\"Extintor de incêndio partes\"*\n\n**Opção B — Inspeção real (mais eficaz):**\nLevar a turma ao corredor mais próximo e inspecionar fisicamente:\n- Verificar manômetro de 2 extintores (pressão adequada?)\n- Verificar rótulo (vencido?)\n- Localizar o abrigo de hidrante mais próximo (tem mangueira? está desobstruído?)\n- Identificar as placas de sinalização (quantas estão visíveis? alguma obstruída?)\n\nRegistrar em formulário de inspeção (evidência documental)."},"verificacao":{"titulo":"Etapa 4 — Verificação de Aprendizagem (5 min)","evidencia":"Evidência documental: registrar nome e respostas.","questoes":[{"pergunta":"O manômetro de um extintor está com o ponteiro na faixa vermelha. Isso indica:","opcoes":[{"texto":"Extintor cheio e pronto para uso","correta":false},{"texto":"Extintor com pressão baixa ou excessiva — necessita manutenção","correta":true},{"texto":"Extintor de CO₂ em condição normal","correta":false},{"texto":"Sinalização decorativa sem função prática","correta":false}]},{"pergunta":"Segundo a NBR 13434, placas com fundo VERDE e figuras brancas indicam:","opcoes":[{"texto":"Equipamentos de combate a incêndio","correta":false},{"texto":"Áreas de perigo e alerta","correta":false},{"texto":"Proibições de segurança","correta":false},{"texto":"Orientação e salvamento (rotas de fuga, saídas, primeiros socorros)","correta":true}]},{"pergunta":"Ao operar um hidrante, por que a mangueira deve ser completamente desenrolada antes de abrir o registro?","opcoes":[{"texto":"Para verificar se há furos antes do uso","correta":false},{"texto":"Para evitar nós e dobras que impedem o fluxo e dificultam a operação","correta":true},{"texto":"Porque a norma proíbe usar mangueira enrolada","correta":false},{"texto":"Para reduzir a pressão na ponta do esguicho","correta":false}]},{"pergunta":"A inspeção mensal do extintor pelo brigadista orgânico deve verificar:","opcoes":[{"texto":"Apenas a data no rótulo","correta":false},{"texto":"Manômetro, lacre, pino de segurança, estado do cilindro e acessibilidade","correta":true},{"texto":"Somente o peso do cilindro","correta":false},{"texto":"Apenas se o extintor está no local correto","correta":false}]},{"pergunta":"Em uma vistoria do CBMSC, qual situação pode resultar em embargo do estabelecimento?","opcoes":[{"texto":"Extintor posicionado a 1,55m do piso (dentro do limite)","correta":false},{"texto":"Sinalização de saída levemente desbotada mas visível","correta":false},{"texto":"Extintor vencido, hidrante sem mangueira e sinalização de saída obstruída","correta":true},{"texto":"Dois extintores do mesmo tipo no mesmo corredor","correta":false}]}]},"fechamento":{"titulo":"Etapa 5 — Fechamento (2 min)","pontos_chave":["Extintor: verifique manômetro, lacre e validade todo mês — equipamento vencido não protege ninguém","Hidrante: mangueira desenrolada primeiro; registro aberto devagar; dois operadores sempre","Sinalização: visível, desobstruída e no local certo — é a primeira orientação em pânico"],"ponte":"Sabemos onde estão os equipamentos e como identificá-los. No B8 vamos entender os sistemas que alertam a todos antes do fogo chegar ao extintor: alarme, detecção e iluminação de emergência."}}$json6$::jsonb where name = 'B7 — Extintores, Hidrantes e Sinalização';
update public.subthemes set conteudo = $json7${"duracao":"45min","norma":"IN 28/2024 CBMSC | NBR 9441 | NBR 10898 | NBR 14276 Anexo B","modulo":"Sistemas Preventivos","contexto":{"titulo":"Etapa 1 — Contexto (5 min)","corpo_md":"**Dado de abertura:**\nO incêndio na boate Kiss (Santa Maria/RS, 2013) matou 242 pessoas. Um dos fatores: a maioria não ouviu ou não reconheceu o alarme de incêndio como real. Estudos mostram que 50% das pessoas ignoram um primeiro alarme, esperando confirmação visual do perigo.\n\n**Ponto central:**\n> O sistema de detecção salva vidas mesmo antes que qualquer pessoa perceba o fogo. O brigadista orgânico precisa entender como funciona para agir corretamente."},"explicacao":{"titulo":"Etapa 2 — Explicação (25 min)","corpo_md":"### 2.1 Sistema de Detecção e Alarme de Incêndio (SDAI) — NBR 9441\n\n#### Componentes básicos\n\n| Componente | Função |\n|------------|--------|\n| **Central de alarme** | Recebe sinais dos detectores e acionadores; processa e emite alertas |\n| **Detectores automáticos** | Identificam a presença de fogo sem intervenção humana |\n| **Acionadores manuais** | Botões que o ocupante pressiona ao perceber o fogo |\n| **Sirenes/strobes** | Alertam auditiva e visualmente os ocupantes |\n| **Painel de sinalização** | Indica a zona em alarme na central |\n\n#### Tipos de Detectores Automáticos\n\n| Tipo | Princípio | Ideal para |\n|------|-----------|-----------|\n| **Iônico** (fumaça) | Ionização do ar por partículas de fumaça | Combustão rápida/com chama (papéis, madeira seca) |\n| **Fotoelétrico** (fumaça) | Dispersão de feixe de luz por partículas | Combustão lenta/com muita fumaça (espumas, plásticos) |\n| **Termovelocimétrico** (calor) | Detecta taxa de elevação rápida da temperatura | Cozinhas, garagens (onde fumaça normal está presente) |\n| **Termostático** (calor) | Aciona em temperatura fixa (ex: 58°C, 72°C) | Ambientes onde a temperatura flutua pouco |\n| **Chama** (UV/IR) | Detecta radiação de chamas | Galpões com PE-EX, hangares, refinarias |\n\n> O tipo de detector é definido em projeto aprovado pelo CBMSC — o brigadista não escolhe, mas deve saber identificar e reportar defeitos.\n\n#### Zonas de Detecção\n- O prédio é dividido em zonas (ex: 1º andar, depósito, cozinha)\n- Quando um detector aciona, a central indica **qual zona** — o brigadista vai verificar especificamente ali\n- Um detector sujo ou defeituoso pode gerar **alarme falso** — sempre verificar antes de autorizar retorno\n\n#### Acionador Manual (botoeira)\n- Posicionado próximo às saídas, a cada 30m ou menos\n- Ao pressionar: aciona o sistema mesmo sem detecção automática\n- Protegido por vidro ou tampa plástica — pressionar apenas em emergência real\n\n---\n\n### 2.2 Procedimento do Brigadista Orgânico ao Ouvir o Alarme\n\n1. **Não ignore** — todo alarme é real até prova em contrário\n2. Verificar a **zona indicada na central**\n3. Ir à zona e **confirmar visualmente** (fumaça, cheiro, chamas)\n4. Se confirmado: acionar 193 + iniciar evacuação\n5. Se alarme falso: registrar ocorrência e comunicar responsável de manutenção\n6. **Nunca silenciar o alarme sem verificação prévia**\n\n---\n\n### 2.3 Iluminação de Emergência (NBR 10898)\n\n#### Função\nGarantir visibilidade suficiente para evacuação segura quando a energia elétrica normal falha.\n\n#### Tipos\n\n| Tipo | Funcionamento |\n|------|--------------|\n| **Bloco autônomo** | Luminária com bateria interna; acende automaticamente ao faltar energia |\n| **Central de emergência** | Sistema centralizado que alimenta luminárias em todo o prédio |\n| **Sinalização de saída iluminada** | Placa de saída com backlight; acende independentemente |\n\n#### Requisitos mínimos (NBR 10898)\n- Autonomia: **mínimo 2 horas** com a energia cortada\n- Nível mínimo de iluminação: 5 lux nas rotas de fuga, 1 lux em pontos críticos\n- Posicionamento: a cada mudança de direção, degrau de escada, saída e junto à sinalização\n\n#### Papel do Brigadista Orgânico\n- Verificar mensalmente se os blocos autônomos **carregam e acendem** quando simulada falta de energia (pressionar o botão de teste)\n- Registrar luminárias com defeito para manutenção"},"recurso":{"titulo":"Etapa 3 — Vídeo / Recurso Prático (10 min)","corpo_md":"**Opção A — Vídeo:**\nBuscar: *\"Sistema de detecção e alarme de incêndio\"* — canal Bombeiros, ABRASEG ou fabricantes como Notifier, Edwards.\n\n**Opção B — Reconhecimento físico (inspeção real):**\nPercorrer o prédio identificando:\n- Quantos detectores existem no corredor/área? Qual o tipo?\n- Onde está o acionador manual mais próximo?\n- Os blocos autônomos estão todos com luz piloto acesa (indicador de carga)?\n- A central de alarme está acessível? Quem tem acesso?\n\nRegistrar em formulário (evidência documental)."},"verificacao":{"titulo":"Etapa 4 — Verificação de Aprendizagem (5 min)","evidencia":"Evidência documental: registrar nome e respostas.","questoes":[{"pergunta":"O detector fotoelétrico é mais indicado para detectar:","opcoes":[{"texto":"Chamas de alta intensidade em galpões abertos","correta":false},{"texto":"Elevação rápida de temperatura em cozinhas","correta":false},{"texto":"Fumaça de combustão lenta, com partículas grandes (espumas, plásticos)","correta":true},{"texto":"Gases tóxicos como CO e CO₂","correta":false}]},{"pergunta":"Ao ouvir o alarme de incêndio, o brigadista orgânico deve PRIMEIRO:","opcoes":[{"texto":"Silenciar o alarme e verificar depois para não causar pânico","correta":false},{"texto":"Ligar imediatamente para os bombeiros sem verificar","correta":false},{"texto":"Verificar a zona indicada na central e confirmar visualmente","correta":true},{"texto":"Aguardar que outro funcionário confirme o incêndio","correta":false}]},{"pergunta":"A autonomia mínima de um bloco autônomo de iluminação de emergência, segundo a NBR 10898, é:","opcoes":[{"texto":"30 minutos","correta":false},{"texto":"1 hora","correta":false},{"texto":"2 horas","correta":true},{"texto":"4 horas","correta":false}]},{"pergunta":"O acionador manual (botoeira) deve ser acionado:","opcoes":[{"texto":"Apenas após o alarme automático já ter disparado","correta":false},{"texto":"Pelo brigadista ao verificar qualquer situação de risco; não aguardar o detector","correta":true},{"texto":"Somente pelo Corpo de Bombeiros ao chegar na edificação","correta":false},{"texto":"Apenas em caso de abandono total do prédio","correta":false}]},{"pergunta":"Um bloco autônomo de iluminação não acende ao pressionar o botão de teste. O que fazer?","opcoes":[{"texto":"Ignorar — é normal blocos antigos não responderem","correta":false},{"texto":"Registrar o defeito e acionar manutenção para troca/recarga","correta":true},{"texto":"Ligar o bloco manualmente na tomada e deixar carregando","correta":false},{"texto":"Cobrir o bloco com fita isolante para indicar que está fora de uso","correta":false}]}]},"fechamento":{"titulo":"Etapa 5 — Fechamento (2 min)","pontos_chave":["Detector certo no local certo — o tipo de detector é definido em projeto; o brigadista identifica, não instala","Todo alarme é real até verificação — silenciar sem checar é a falha mais grave do brigadista","Iluminação de emergência: autonomia mínima de 2h; testar mensalmente o botão de teste"],"ponte":"Com o alarme tocando e a iluminação ativa, o próximo passo é a evacuação segura. No B9, o último componente do Básico, vamos entender as saídas de emergência — o que a norma exige, como devem estar e qual o papel do brigadista nesse processo."}}$json7$::jsonb where name = 'B8 — Alarme, Detecção e Iluminação de Emergência';
update public.subthemes set conteudo = $json8${"duracao":"30min","norma":"IN 28/2024 CBMSC | NBR 9077 | NBR 14276 Anexo B","modulo":"Sistemas Preventivos","contexto":{"titulo":"Etapa 1 — Contexto (3 min)","corpo_md":"**Dado de abertura:**\nNo incêndio da boate Kiss, investigações apontaram que muitas vítimas morreram comprimidas na única saída desbloqueada, enquanto outras saídas estavam trancadas ou obstruídas. O princípio é simples: **saída de emergência que não se abre na hora certa é uma armadilha**.\n\n**Pergunta:**\n> \"Quantas saídas de emergência vocês conhecem neste prédio? Conseguiriam sair com fumaça densa, no escuro, em 60 segundos?\""},"explicacao":{"titulo":"Etapa 2 — Explicação (15 min)","corpo_md":"### 2.1 Rota de Fuga e Saída de Emergência (NBR 9077)\n\n#### Definições\n\n| Termo | Definição |\n|-------|-----------|\n| **Rota de fuga** | Caminho protegido desde qualquer ponto até o exterior seguro |\n| **Saída de emergência** | Conjunto: porta + corredor + escada + saída final ao exterior |\n| **Ponto de encontro** | Local externo seguro onde os ocupantes se reúnem após evacuação |\n| **Porta corta-fogo** | Porta com resistência ao fogo (30–120 min) que compartimenta a edificação |\n\n#### Largura Mínima das Rotas (NBR 9077)\n\n| Situação | Largura mínima |\n|----------|---------------|\n| Corredores de rota de fuga | 1,20m (100 pessoas) |\n| Escadas de emergência | 1,20m |\n| Portas de saída | 0,80m (mínimo) |\n\n> Nunca obstruir rotas com móveis, paletes, carrinhos ou equipamentos — mesmo temporariamente.\n\n#### Distância Máxima de Caminhamento\n- Varia conforme o risco da edificação (baixo, médio, alto)\n- Em geral: 30–50m até a saída mais próxima em edificações de risco médio\n- O projeto aprovado pelo CBMSC define a distância para cada caso\n\n### 2.2 Porta Corta-Fogo\n\n- Deve permanecer **sempre fechada** (com o mecanismo de mola/fechador automático funcionando)\n- **Nunca bloquear** com cunha, cadeira ou objeto — a porta fechada compartimenta o fogo\n- O brigadista deve verificar se fechadores estão funcionando\n- Resistência ao fogo: identificada pela sigla **P-xx** (ex: P-30, P-60, P-90 = minutos de resistência)\n\n### 2.3 Sinalização da Rota de Fuga\n\n- Placa de saída iluminada em cada ponto de decisão (bifurcação, mudança de direção)\n- Sinalização fotoluminescente no piso (auxilia quando há fumaça baixa)\n- Ponto de encontro identificado externamente\n\n### 2.4 Papel do Brigadista Orgânico nas Saídas\n\nDurante inspeção (rotina):\n- Verificar se rotas estão desobstruídas\n- Verificar se portas corta-fogo fecham completamente\n- Verificar sinalização visível e iluminada\n\nDurante evacuação:\n- **Não corre** — guia a evacuação de forma organizada\n- Varre o setor de responsabilidade (verifica todos os banheiros, salas, depósitos)\n- Auxilia pessoas com mobilidade reduzida\n- Reporta ao líder da brigada ao chegar no ponto de encontro"},"recurso":{"titulo":"Etapa 3 — Recurso Prático (8 min)","corpo_md":"**Atividade — Mapeamento da rota:**\nDistribuir planta baixa simplificada do andar/setor. Os alunos:\n1. Identificar as 2 saídas de emergência mais próximas do local de trabalho\n2. Traçar o caminho até o ponto de encontro\n3. Identificar portas corta-fogo no percurso\n4. Apontar pelo menos 1 obstáculo potencial na rota\n\nDebriefe: compartilhar os pontos de obstrução identificados — gera lista de ação real para a empresa."},"verificacao":{"titulo":"Etapa 4 — Verificação de Aprendizagem (4 min)","evidencia":"Evidência documental: registrar nome e respostas.","questoes":[{"pergunta":"Uma porta corta-fogo deve permanecer:","opcoes":[{"texto":"Aberta durante o expediente para facilitar a circulação","correta":false},{"texto":"Sempre fechada, com o fechador automático funcionando","correta":true},{"texto":"Travada com cadeado durante a noite","correta":false},{"texto":"Aberta apenas nas rotas de fuga principais","correta":false}]},{"pergunta":"Durante uma evacuação, o brigadista orgânico deve:","opcoes":[{"texto":"Ser o primeiro a sair para indicar o caminho aos demais","correta":false},{"texto":"Aguardar no ponto de encontro para contar as pessoas","correta":false},{"texto":"Varrer o setor verificando que todos saíram, auxiliar mobilidade reduzida e reportar ao líder da brigada","correta":true},{"texto":"Combater o fogo enquanto os outros evacuam","correta":false}]},{"pergunta":"A largura mínima de um corredor de rota de fuga, conforme NBR 9077, é:","opcoes":[{"texto":"0,80m","correta":false},{"texto":"1,00m","correta":false},{"texto":"1,20m","correta":true},{"texto":"1,50m","correta":false}]}]},"fechamento":{"titulo":"Etapa 5 — Fechamento (2 min)","pontos_chave":["Duas saídas sempre — conheça as duas rotas de fuga do seu setor antes de precisar delas","Porta corta-fogo fechada salva vidas — nunca bloquear, mesmo por 1 minuto","Brigadista varre o setor — não abandona antes de confirmar que a área está vazia"],"ponte":"Este é o fim do Curso Básico de 8 horas. Você agora conhece o triângulo/tetraedro do fogo, as 6 classes de incêndio incluindo a Classe L de baterias de lítio, os agentes extintores corretos, primeiros socorros e os sistemas preventivos da sua empresa. O certificado do Básico habilita o brigadista orgânico conforme a IN 28/2024 do CBMSC. O próximo passo é o Curso Intermediário (16h), que aprofunda todos esses temas e inclui o módulo de Atividades da Brigada."}}$json8$::jsonb where name = 'B9 — Saídas de Emergência';
